INSERT OR IGNORE INTO authors (id, slug, name, bio, role, image, image_alt, profile_url, created_at, updated_at) VALUES (1, 'oluwashola-busari', 'Oluwashola Busari', 'The founder of Sholynk Technology. Has a background in Mass Communication, Software Engineering, Digital Marketing, and Data Analysis. He is focused on explaining technical concepts in very simple terms.', 'Founder, Software Engineer and Tech Journalist', 'assets/brand/my_pic.png', 'Portrait photo of Oluwashola Busari', 'about.html', '2026-10-18 11:59:23', '2026-10-18 11:59:23');

