INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (1, 1, 'Adults'' media use and attitudes', 'Ofcom', '', '2026-04-02', 'https://www.ofcom.org.uk/media-use-and-attitudes/media-habits-adults/adults-media-use-and-attitudes', 'official', '', '2026-08-16', 'Ofcom''s annual evidence base on media use, attitudes and understanding among UK adults aged 16 and over, drawn from its Adults'' Media Literacy Tracker.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (2, 1, 'Is the UK falling out of love with social media?', 'The Guardian', '', '2026-04-05', 'https://www.theguardian.com/news/ng-interactive/2026/apr/05/uk-social-media-apps-share', 'journalism', '', '2026-08-16', 'Reporting on Ofcom findings that 49% of adult social media users now post, share or comment against 61% in 2024; that the share saying the benefits of being online outweigh the risks fell to 59% from 72%; that 40% report spending too much time on screens most days; and that average daily time online rose to four hours thirty minutes.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (3, 1, 'Online Nation 2024 report', 'Ofcom', '', '2024-11-28', 'https://www.ofcom.org.uk/siteassets/resources/documents/research-and-data/online-research/online-nation/2024/online-nation-2024-report.pdf?v=386238', 'primary', '', '2026-08-16', 'Passive-panel measurement showing that three-quarters of the time UK adults spent online per day in May 2024 was on smartphones.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (4, 2, '2025 Developer Survey', 'Stack Overflow', '', '2025-07-29', 'https://survey.stackoverflow.co/2025/', 'primary', '', '2026-08-16', 'Self-reported language use (JavaScript 66%, HTML/CSS 61.9%, SQL 58.6%, Python 57.9%, with Python up seven percentage points year on year); 84% of respondents using or planning to use AI tools, up from 76%; 66% citing AI answers that are almost right as their biggest frustration; 45% reporting that debugging AI-generated code takes longer; and 20% reporting reduced confidence in their own problem-solving.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (5, 2, 'OWASP Top Ten Web Application Security Risks', 'OWASP Foundation', '', '', 'https://owasp.org/www-project-top-ten/', 'official', '', '2026-08-16', 'A consensus standard-awareness document listing the most critical security risks to web applications, currently published as the OWASP Top Ten 2025.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (6, 3, 'NIST Releases First 3 Finalized Post-Quantum Encryption Standards', 'National Institute of Standards and Technology', '', '2024-08-13', 'https://www.nist.gov/news-events/news/2024/08/nist-releases-first-3-finalized-post-quantum-encryption-standards', 'primary', '', '2026-08-16', 'NIST finalised its principal set of quantum-resistant encryption standards after an eight-year effort, encourages administrators to begin transitioning immediately, and notes that some experts predict a device able to break current encryption could appear within a decade.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (7, 3, 'What Is Post-Quantum Cryptography?', 'National Institute of Standards and Technology', '', '', 'https://www.nist.gov/cybersecurity-and-privacy/what-post-quantum-cryptography', 'official', '', '2026-08-16', 'NIST''s explanation of why current public-key cryptography is vulnerable to quantum attack and what replacing it involves.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (8, 3, 'Elliptic-curve cryptography', 'Wikipedia', '', '', 'https://en.wikipedia.org/wiki/Elliptic-curve_cryptography', 'reference', '', '2026-08-16', 'Elliptic-curve cryptography underpins widely used protocols including Transport Layer Security and Bitcoin, which is why a quantum attack on it would have broad consequences.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (9, 4, 'MMMU-Pro: A More Robust Multi-discipline Multimodal Understanding Benchmark', 'arXiv (ACL 2025 Main)', 'Xiang Yue and colleagues', '2025-05-22', 'https://arxiv.org/abs/2409.02813', 'research', '10.48550/arXiv.2409.02813', '2026-08-16', 'Model accuracy falls by 16.8 to 26.9 percentage points on MMMU-Pro compared with MMMU, and the benchmark filters out questions answerable by text-only models.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (10, 4, 'Video-MMMU: Evaluating Knowledge Acquisition from Multi-Discipline Professional Videos', 'arXiv', '', '2025-01-23', 'https://arxiv.org/abs/2501.13826', 'research', '', '2026-08-16', 'Model performance declines progressively as the cognitive demand of video-based tasks increases, across 300 expert-level videos in six disciplines.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (11, 4, 'Gemini model family: published benchmark results', 'Google DeepMind', '', '', 'https://deepmind.google/models/gemini/', 'official', '', '2026-08-16', 'Vendor-published scores for long video understanding, chart reasoning and document comprehension, used here as vendor-reported figures, not independent evaluation.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (12, 5, 'Implementing the Guiding and Establishing National Innovation for US Stablecoins Act', 'Office of the Comptroller of the Currency, Federal Register', '', '2026-03-02', 'https://www.federalregister.gov/documents/2026/03/02/2026-04089/implementing-the-guiding-and-establishing-national-innovation-for-us-stablecoins-act-for-the', 'primary', '', '2026-08-16', 'Proposed 12 CFR Part 15 requirements including the $5 million minimum capital floor for de novo federal issuers, the $10 billion threshold for transition to federal oversight, and the OCC''s use of private forecasts with an upper bound of $500 billion in 2026 issuance.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (13, 5, 'OCC Proposes Regulations to Implement the GENIUS Act', 'Sullivan & Cromwell LLP', '', '2026-04-06', 'https://www.sullcrom.com/insights/memo/2026/March/OCC-Proposes-Regulations-Implement-GENIUS-Act', 'reference', '', '2026-08-16', 'Analysis of the proposed two business day limit on timely redemption and the requirement that issuers with at least $25 billion outstanding hold 0.5% of reserves in insured deposits, capped at $500 million.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (14, 5, 'What You Need To Know About the New Stablecoin Legislation: Analyzing the GENIUS Act', 'Arnold & Porter', '', '2025-07-21', 'https://www.arnoldporter.com/en/perspectives/advisories/2025/07/new-stablecoin-legislation-analyzing-the-genius-act', 'reference', '', '2026-08-16', 'The GENIUS Act permits only issuers below $10 billion in market capitalisation to opt for a state-level regulatory regime, with annual state recertification.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (15, 5, 'BIS says stablecoins fall short as money, warns of emerging-market risks in annual report', 'The Block', '', '2026-06-28', 'https://www.theblock.co/news/regulation/2026-06-28-bis-says-stablecoins-fall-short-as-money-warns-of-emerging-market-risks-in-annual-report-406466', 'journalism', '', '2026-08-16', 'Reporting on the BIS Annual Economic Report 2026 chapter arguing stablecoins fall short on singleness, elasticity, interoperability and integrity, and modelling a slightly negative medium-term output effect at $1 trillion to $3 trillion in market value.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (16, 5, 'Narrow stablecoins: Redemption, runs, and risk', 'The Quarterly Review of Economics and Finance, Elsevier', 'Zane Mullins', '2026-06', 'https://www.sciencedirect.com/science/article/pii/S1062976926000384', 'research', '10.1016/j.qref.2026.102143', '2026-08-16', 'Peer-reviewed open-access analysis arguing that properly collateralised fiat-pegged stablecoins are not inherently run-prone, and that for issuers holding only cash equivalents redemption risk arises mainly where a run forces loss-making asset liquidation.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (17, 6, 'IOC enters a new era with the creation of Olympic Esports Games', 'International Olympic Committee', '', '2024-07-23', 'https://www.olympics.com/ioc/news/ioc-enters-a-new-era-with-the-creation-of-olympic-esports-games-first-games-in-2025-in-saudi-arabia', 'official', '', '2026-08-16', 'The 142nd IOC Session unanimously endorsed the creation of an Olympic Esports Games, and the IOC entered a 12-year partnership with the National Olympic Committee of Saudi Arabia.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (18, 6, 'First Olympic Esports Games Confirmed for 2027 in Saudi Arabia, Roadmap Starts This Year', 'Saudi Press Agency', '', '2025-02-11', 'https://www.spa.gov.sa/en/N2259921', 'official', '', '2026-08-16', 'Confirmation that the inaugural Olympic Esports Games would take place in 2027, not 2025, and that the Esports World Cup Foundation was named founding partner.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (19, 6, 'Olympic Esports Games', 'International Olympic Committee', '', '', 'https://www.olympics.com/ioc/olympic-esports-games', 'official', '', '2026-08-16', 'IOC statement that the Olympic Esports Games were approved in July 2024 as a landmark initiative bridging esports and traditional sport.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
INSERT OR IGNORE INTO article_sources (id, article_id, title, publisher, author, published_at, url, type, doi, accessed_at, supports, created_at, updated_at) VALUES (20, 6, 'Newzoo Global Games Market Report 2025', 'Newzoo', '', '2025-09-09', 'https://newzoo.com/resources/trend-reports/newzoo-global-games-market-report-2025', 'primary', '', '2026-08-16', 'Global games market revenues of $188.8 billion in 2025 across a player base of 3.6 billion, with console the fastest-growing segment at 5.5% year on year.', '2026-10-18 11:59:23', '2026-10-18 11:59:23');
